/// Native replay implementations for net bindings.
#[inline]
fn destack_net_accept_replay(
    context: &RuntimeCallContext,
    out: *mut resource::SocketHandle,
    listener: resource::ListenerHandle,
) -> RuntimeResult<()> {
    let _ = &listener;

    context.replay().run_binding(
        ACCEPT,
        || unsafe { platform_native::destack_net_accept(context, out, listener) },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_replay = result_value;
                let payload = AcceptReplay {
                    result: Ok(result_replay),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    AcceptReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native = value;
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

