#[inline]
fn destack_net_local_address_replay(
    context: &RuntimeCallContext,
    out: *mut SocketAddress,
    handle: resource::SocketHandle,
) -> RuntimeResult<()> {
    let _ = &handle;

    context.replay().run_binding(
        LOCAL_ADDRESS,
        || unsafe { platform_native::destack_net_local_address(context, out, handle) },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_replay_host = unsafe { result_value.host.as_str()? }.to_string();
                let result_replay_port = result_value.port;
                let result_replay_family = result_value.family;
                let result_replay = SocketAddressReplay {
                    host: result_replay_host,
                    port: result_replay_port,
                    family: result_replay_family,
                };
                let payload = LocalAddressReplay {
                    result: Ok(result_replay),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    LocalAddressReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_host = context.store_string(&value.host);
                    let value_native_port = value.port;
                    let value_native_family = value.family;
                    let value_native = SocketAddress {
                        host: value_native_host,
                        port: value_native_port,
                        family: value_native_family,
                    };
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

